#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <limits>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");SessionTimelineDocumentCandidate doc(loadGraph(argv[1]));uint32_t id=UINT32_MAX;float before=0;for(uint32_t i=0;i<doc.graph().elements.size();++i){const auto&e=doc.graph().elements[i];if(doc.graph().strings.at(e.type)!="DmeExpressionOperator")continue;auto*a=namedAttribute(doc.graph(),e,"value");if(a&&a->type==3){id=i;before=wireFloat(a->values[0]);break;}}if(id==UINT32_MAX)throw std::runtime_error("no expression input");for(float invalid:{std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-std::numeric_limits<float>::infinity()}){bool finiteRejected=false;try{doc.setScalarFloat(id,"value",invalid);}catch(const std::runtime_error&){finiteRejected=true;}if(!finiteRejected||doc.dirty()||wireFloat(namedAttribute(doc.graph(),doc.graph().elements[id],"value")->values[0])!=before)throw std::runtime_error("non-finite scalar was accepted or changed document");}float next=before==0.25f?0.75f:0.25f;bool rejected=false;try{doc.transact([&](auto&staged){return staged.setScalarFloat(id,"value",next);},[](const Graph&){throw std::runtime_error("publish failed");});}catch(const std::runtime_error&){rejected=true;}if(!rejected||doc.dirty()||doc.undo())throw std::runtime_error("rejected scalar publish committed");if(!doc.transact([&](auto&staged){return staged.setScalarFloat(id,"value",next);},[](const Graph&){} )||!doc.dirty())throw std::runtime_error("scalar edit transaction");if(doc.setScalarFloat(id,"value",next))throw std::runtime_error("equal edit recorded");if(doc.undo()!=1||doc.dirty()||wireFloat(namedAttribute(doc.graph(),doc.graph().elements[id],"value")->values[0])!=before)throw std::runtime_error("scalar document undo");if(doc.redo()!=1||!doc.dirty()||wireFloat(namedAttribute(doc.graph(),doc.graph().elements[id],"value")->values[0])!=next)throw std::runtime_error("scalar document redo");std::cout<<"document_scalar_edit_checks=8 finite_guard transaction undo redo\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
